import { useId } from "react";
import Svg, { Circle, Defs, LinearGradient, Path, Stop } from "react-native-svg";
import {
  BRAND_CENTRE_LINE,
  BRAND_ECG_PATH,
  BRAND_GRADIENT_FROM,
  BRAND_GRADIENT_TO,
  BRAND_OUTLINE_PATH,
  BRAND_OUTLINE_STROKE_WIDTH,
  BRAND_STROKE_WIDTH,
} from "../constants/brandVector";

/**
 * The Migraine Detector mark: a lobed brain outline with an ECG waveform
 * running through it, on the brand gradient disc.
 *
 * The vector is generated by scripts/extract_brand_vector.py from the Figma
 * reference and lives in src/constants/brandVector.ts, which the launcher
 * icon renderer reads too, so the two can never drift apart.
 *
 * The app mark and the Mira assistant mark are the same symbol - the brand
 * sheet shows one mark at two sizes - so this component has no variant.
 */
export function BrandGlyph({ size = 52 }: { size?: number }) {
  const id = `brand${useId().replace(/[^a-z0-9]/gi, "")}`;

  return (
    <Svg
      width={size}
      height={size}
      viewBox="0 0 64 64"
      accessibilityLabel="Migraine Detector"
    >
      <Defs>
        <LinearGradient id={id} x1="0" y1="0" x2="1" y2="1">
          <Stop offset="0" stopColor={BRAND_GRADIENT_FROM} />
          <Stop offset="1" stopColor={BRAND_GRADIENT_TO} />
        </LinearGradient>
      </Defs>
      <Circle cx="32" cy="32" r="32" fill={`url(#${id})`} />
      <Path
        d={BRAND_OUTLINE_PATH}
        fill="none"
        stroke="#FFFFFF"
        strokeWidth={BRAND_OUTLINE_STROKE_WIDTH}
        strokeLinejoin="round"
        strokeLinecap="round"
      />
      <Path
        d={`M${BRAND_CENTRE_LINE.x} ${BRAND_CENTRE_LINE.y0}L${BRAND_CENTRE_LINE.x} ${BRAND_CENTRE_LINE.y1}`}
        stroke="#FFFFFF"
        strokeWidth={BRAND_STROKE_WIDTH}
        strokeLinecap="round"
        fill="none"
      />
      <Path
        d={BRAND_ECG_PATH}
        fill="none"
        stroke="#FFFFFF"
        strokeWidth={BRAND_STROKE_WIDTH}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </Svg>
  );
}
